import math

def solution(input_str):
    # Parse the input
    lines = input_str.strip().split('\n')
    n, m = int(lines[0].split()[0]), int(lines[0].split()[1])
    ops = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        ops.append(parts)

    # ans[v] = earliest time step to reach value v, -1 if unreachable
    ans = [-1] * (m + 1)

    # Initially we can have 0 bananas at time 0
    all_reachable = {0}

    for i in range(1, n + 1):
        t, x_num, y = ops[i - 1]
        x = x_num / 100000.0

        # Values from previous time step
        prev_reachable = all_reachable

        # Generate all values reachable at this step from each value in prev_reachable
        newly_reachable = set()
        for v in prev_reachable:
            # For each choice of a from 0 to y
            for a in range(y + 1):
                if t == 1:
                    cur = v
                    for _ in range(a):
                        cur = math.ceil(cur + x)
                else:
                    cur = v
                    for _ in range(a):
                        cur = math.ceil(cur * x)

                # Only track values in the valid range [1, m] for output purposes
                if 1 <= cur <= m:
                    newly_reachable.add(cur)

        # Record earliest time step for each newly reached value
        for v in newly_reachable:
            if ans[v] == -1:
                ans[v] = i

        # All currently reachable values for next step
        all_reachable.update(newly_reachable)

    # Output the answers for values 1 to m
    return ' '.join(map(str, ans[1:]))
