def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    t = int(lines[0])
    line_idx = 1
    results = []

    for _ in range(t):
        if line_idx >= len(lines):
            break
        parts = lines[line_idx].split()
        line_idx += 1
        n, m = int(parts[0]), int(parts[1])

        matrix = []
        for i in range(n):
            if line_idx >= len(lines):
                break
            line_data = lines[line_idx]
            line_idx += 1
            matrix.append(list(line_data[:m]))

        count = 0

        # Count axis-aligned squares
        for r1 in range(n - 1):
            for c1 in range(m - 1):
                for size in range(2, min(n - r1, m - c1) + 1):
                    r2 = r1 + size - 1
                    c2 = c1 + size - 1

                    # Check border is all 1s
                    top_ok = all(matrix[r1][c] == 1 for c in range(c1, c2 + 1))
                    bottom_ok = all(matrix[r2][c] == 1 for c in range(c1, c2 + 1))
                    left_ok = all(matrix[r][c1] == 1 for r in range(r1, r2 + 1))
                    right_ok = all(matrix[r][c2] == 1 for r in range(r1, r2 + 1))

                    if top_ok and bottom_ok and left_ok and right_ok:
                        # Interior must be all 0s
                        interior_ok = all(
                            matrix[r][c] != 1 
                            for r in range(r1 + 1, r2) 
                            for c in range(c1 + 1, c2)
                        )

                        # Check no adjacent 1s on boundary (8 neighbors of frame)
                        valid = True
                        for r in range(r1, r2 + 1):
                            for c in range(c1, c2 + 1):
                                # Check 8 neighbors
                                for dr in range(-1, 2):
                                    for dc in range(-1, 2):
                                        if dr == 0 and dc == 0:
                                            continue
                                        nr, nc = r + dr, c + dc
                                        if 0 <= nr < n and 0 <= nc < m:
                                            if matrix[nr][nc] == 1:
                                                valid = False
                                                break
                                    if not valid:
                                        break
                            if not valid:
                                break

                        if interior_ok and valid:
                            count += 1

        # Count diagonal (diamond) squares
        for r in range(n):
            for c in range(m):
                if matrix[r][c] != 1:
                    continue

                for radius in range(1, min(n, m)):
                    # Diamond of radius(s) forms a pattern where
                    # each side has k cells, creating a diamond shape
                    # Total cells: 4*(radius) for diamond of "size" radius
                    # Check all border cells of diamond
                    border_ok = True
                    # Top-left corner to center-top
                    if radius > 1 and 0 <= c + radius < m and r >= 0:
                        # Check anti-diagonal
                        pass

                    # A diamond of size k has 4 cells on each side of the "square" border
                    # For a diamond, check all cells where |r - center_r| + |c - center_c| == radius
                    # and the boundary cells are all 1s

                    # For diamond centered at (r,c)
                    cells_to_check = []
                    for dr in range(-radius, radius + 1):
                        for dc in range(-radius, radius + 1):
                            if abs(dr) + abs(dc) == radius:
                                cells_to_check.append((r + dr, c + dc))

                    # Remove duplicates
                    cells_to_check = sorted(set(cells_to_check))

                    if all(
                        0 <= cell[0] < n and 0 <= cell[1] < m and matrix[cell[0]][cell[1]] == 1
                        for cell in cells_to_check
                    ):
                        # Now check it's isolated from other 1s
                        valid = True
                        for cell in cells_to_check:
                            for dr in range(-1, 2):
                                for dc in range(-1, 2):
                                    if dr == 0 and dc == 0:
                                        continue
                                    nr, nc = cell[0] + dr, cell[1] + dc
                                    if 0 <= nr < n and 0 <= nc < m:
                                        if matrix[nr][nc] == 1:
                                            valid = False
                                            break
                                if not valid:
                                    break
                            if not valid:
                                break

                        if valid and radius >= 1:
                            count += 1

        results.append(str(count))

    return '\n'.join(results)
