def solution(input_str):
    """
    Solution using a tree DP approach.

    dp[u][s] = maximum product of component sizes from subtree rooted at u,
               where s nodes are in the component containing u.

    When processing a child v:
    - Cut edge (u,v): v's subtree becomes separate, contributing sz[u] as a component
    - Keep edge (u,v): merge components, multiplying their sizes

    Time complexity: O(n^3) worst case, but much faster on average due to tree structure
    Space complexity: O(n^2)
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    if n == 1:
        return '1'

    if n == 0:
        return '1'

    adj = [[] for _ in range(n + 1)]
    for i in range(1, n):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    sz = [0] * (n + 1)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    def dfs(u, p):
        sz[u] = 1
        dp[u][1] = 1

        for v in adj[u]:
            if v != p:
                dfs(v, u)

        # Merge each child's DP into DP[u]
        for v in adj[u]:
            if v != p:
                new_dp = [0] * (n + 1)

                # Try all combinations of sizes from u and v
                for s_u in range(1, n + 1):
                    if dp[u][s_u] == 0:
                        continue

                    for s_v in range(1, sz[v] + 1):
                        if dp[v][s_v] == 0:
                            continue

                        # Option 1: Cut edge (u,v) - v's subtree becomes separate
                        # Product contribution: sz[v]
                        prod = dp[u][s_u] * sz[v]
                        new_dp[s_u] = max(new_dp[s_u], prod)

                        # Option 2: Keep edge (u,v) - merge v into u's component
                        new_size = s_u + s_v
                        prod = dp[u][s_u] * dp[v][s_v] * s_v
                        if new_size <= n:
                            new_dp[new_size] = max(new_dp[new_size], prod)

                for s in range(1, n + 1):
                    dp[u][s] = max(dp[u][s], new_dp[s])

                sz[u] += sz[v]

    dfs(1, -1)
    return str(max(dp[1]))
