        # Brute force for small n
        for mask in range(1 << n):
            msg_counts = [0] * n
            for i in range(n):
                if (mask >> i) & 1:
                    for j in range(n):
                        if contacts[i][j]:
                            msg_counts[j] += 1

            valid = True
            for j in range(n):
