            if not dp(a, b + 1):
                current_player_wins = True

        # Special handling for a=1: can force infinite game (draw)
        if a == 1:
            # Check if can always avoid losing
            can_force_draw = True
            # If increasing a puts next player in losing state
            if not breakpoint_check(2, b, log_n):
                can_force_draw = not dp(2, b)
                if can_force_draw:
                    current_player_wins = True
            memo[(a, b)] = current_player_wins
            return current_player_wins

        memo[(a, b)] = current_player_wins
        return current_player_wins

    def __floor_check(x, y, log_n):
        """Safe check to see if x^y < n without overflow"""
        if log_n == 0:  # n=1
            return y == 0 or x == 0
        result = y * math.log10(x)
        return result < log_n

