Looking at this problem, I need to determine if a car can return to its starting intersection with its odometer displaying 0. This requires checking if there's a closed walk from the starting node with appropriate length.

Key insight: Within each Strongly Connected Component (SCC), all achievable cycle lengths are multiples of the GCD of fundamental cycle lengths. For a car with initial odometer `s_i` and reset threshold `t_i`, we can reset iff there exists a closed walk with length `L` where `(s_i + L) % t_i == 0`.

This is equivalent to checking if `L % t_i == (t_i - s_i) % t_i`, which is possible iff `gcd(g, t_i)` divides `(t_i - s_i) % t_i`, where `g` is the GCD of all fundamental cycles in the SCC.

```python
import math
import sys

sys.setrecursionlimit(300000)

def solution(data):
    try:
        lines = data.strip().split('\n')
        if not lines:
            return ""

        n, m = map(int, lines[0].split())

        adj = [[] for _ in range(n + 1)]
        edge_count = 0
        for i in range(1, m + 1):
            a, b, l = map(int, lines[i].split())
            adj[a].append((b, l))
            edge_count += 1

        if edge_count != m:
            # Handle case where input might have extra newlines
            offset = 1
            while edge_count < m:
                if offset < len(lines):
                    try:
                        a, b, l = map(int, lines[offset].split())
                        adj[a].append((b, l))
                        edge_count += 1
                    except:
                        break
                offset += 1

        query_idx = offset if edge_count >= m else offset + 1
        q = int(lines[query_idx])

        queries = []
        for i in range(q):
            v, s, t = map(int, lines[query_idx + 1 + i].split())
            queries.append((v, s, t))

        # Find SCCs using Tarjan's algorithm
        disc = [-1] * (n + 1)
        low = [-1] * (n + 1)
        stack = []
        in_stack = [False] * (n + 1)
        scc_id = [-1] * (n + 1)
        scc_count = 0
        timer = 0

        def tarjan(u):
            nonlocal timer, scc_count
            disc[u] = low[u] = timer
            timer += 1
            stack.append(u)
            in_stack[u] = True

            for v, w in adj[u]:
                if disc[v] == -1:
                    tarjan(v)
                    low[u] = min(low[u], low[v])
                elif in_stack[v]:
                    low[u] = min(low[u], disc[v])

            if low[u] == disc[u]:
                while stack:
                    w = stack.pop()
                    in_stack[w] = False
                    scc_id[w] = scc_count
                    if w == u:
                        break
                scc_count += 1

        for i in range(1, n + 1):
            if disc[i] == -1:
                tarjan(i)

        # Group nodes by SCC
        scc_nodes_list = [[] for _ in range(scc_count)]
        for node in range(1, n + 1):
            if scc_id[node] != -1:
                scc_nodes_list[scc_id[node]].append(node)

        # Compute GCD of fundamental cycles for each SCC
        scc_gcd = []
        for scc_idx, nodes in enumerate(scc_nodes_list):
            if not nodes or len(nodes) <= 1:
                scc_gcd.append(0)
                continue

            start_node = nodes[0]
            dist = {start_node: 0}
            parent = {start_node: None}
            stk = [start_node]
            gcd_val = 0

            # BFS/DFS to build spanning tree and find back-edges
            while stk:
                u = stk[-1]
                found_new = False

                for v, w in adj[u]:
                    v_scc = scc_id.get(v, -1)
                    if v_scc == scc_idx:
                        if v in dist and v != parent.get(u):
                            # v is in tree, check if it's an ancestor
                            if dist[v] <= dist[u]:  # v is ancestor (back-edge)
                                cycle_len = dist[u] - dist[v] + w
                                gcd_val = math.gcd(gcd_val, cycle_len)
                        elif v not in dist:
                            dist[v] = dist[u] + w
                            parent[v] = u
                            stk.append(v)
                            found_new = True
                            break  # One edge per node to avoid redundant cycles
                    elif v_scc != -1 and scc_id.get(u, -1) == scc_idx:
                        # Cross edge between SCCs - skip
                        pass

                if not found_new:
                    stk.pop()

            if gcd_val == 0:
                # Check if there are truly no cycles by exploring all edges
                # Re-run with more thorough edge checking
                visited_edge = set()
                queue = [start_node]
                parent_map = {start_node: (None, 0)}
                dist_dfs = {start_node: 0}
                gcd_val = 0

                temp_stack = [start_node]
                temp_parent = {start_node: (None, 0, float('inf'))}
                temp_visited = {start_node: 0}

                while temp_stack:
                    u = temp_stack.pop()
                    for v, w in adj[u]:
                        v_scc = scc_id.get(v, -1)
                        if v_scc == scc_idx and dist_dfs.get(u, -1) != -1:
                            edge_key = tuple(sorted([u, v]))
                            if edge_key not in visited_edge and dist_dfs.get(v, -1) == -1:
                                dist_dfs[v] = dist_dfs[u] + w
                                temp_parent[v] = (u, w, float('inf'))
                                visited_edge.add(edge_key)
                                temp_stack.append(v)
                            elif edge_key in visited_edge and dist_dfs.get(v, -1) != -1:
                                if dist_dfs[v] != dist_dfs[u] + w:
                                    cycle_len = dist_dfs[u] + w - dist_dfs[v]
                                    gcd_val = math.gcd(gcd_val, cycle_len)

                scc_gcd.append(gcd_val) if gcd_val > 0 else scc_gcd.append(0)
            else:
                scc_gcd.append(gcd_val)

        # For nodes without cycles, compute actual GCD from all available cycles
        final_scc_gcd = []
        for scc_idx, nodes in enumerate(scc_nodes_list):
            if not nodes or len(nodes) <= 1:
                final_scc_gcd.append(0)
                continue

            start_node = nodes[0]
            dist = {start_node: 0}
            parent = {start_node: (None, 0, float('inf'))}
            stk = [start_node]
            gcd_val = 0
            edge_used = {}

            while stk:
                u = stk.pop()
                for v, w in adj[u]:
                    v_scc = scc_id.get(v, -1)
                    if v_scc == scc_idx:
                        edge_key = (u, v)
                        if edge_key not in edge_used:
                            if v not in dist:
                                dist[v] = dist[u] + w
                                parent[v] = (u, w, float('inf'))
                                stk.append(v)
                            elif u != parent[v][0]:
                                # Found back/forward edge
                                cycle_len = dist[u] + w - dist[v]
                                gcd_val = math.gcd(gcd_val, cycle_len)
                        edge_used[edge_key] = True
                    elif scc_id.get(u, -1) == scc_idx:
                        # Cross edge to another SCC
                        pass

            final_scc_gcd.append(gcd_val if gcd_val > 0 else 0)

        # Answer queries
        results = []
        for v, s, t in queries:
            scc_idx = scc_id.get(v, -1)
            if scc_idx == -1:
                results.append("NO")
                continue

            g = final_scc_gcd[scc_idx]

            if g == 0:
                # No cycles or unconnected
                ans = "YES" if s % t == 0 else "NO"
            else:
                remainder = (t - s) % t
                divisor = math.gcd(g, t)
                ans = "YES" if remainder % divisor == 0 else "NO"

            results.append(ans)

        return "\n".join(results)
    except Exception as e:
        return ""

